import unittest
from tools.job_key import slugify, make_key

class TestDanishJobKey(unittest.TestCase):
    def test_danish(self):
        self.assertEqual(slugify("Ærø"), "aeroe")
        self.assertEqual(slugify("Rø"), "roe")
        self.assertEqual(make_key("Ærø", "Kommune"), "aeroe_kommune")
        self.assertEqual(make_key("Rø", "Kommune"), "roe_kommune")

if __name__ == "__main__":
    unittest.main()

from hypothesis import given, strategies as st
